param(    [Parameter(Mandatory=$true)][string]$ProgressExe,    [Parameter(Mandatory=$true)][string]$CpStream,    [Parameter(Mandatory=$true)][string]$CpInternal)$Root = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)$Job = Join-Path $env:TEMP ("jc-ide-" + [guid]::NewGuid().ToString("N"))$Helper = Join-Path $Root "progress\\abl\\jc-bridge.p"$Source = Join-Path $Root "progress\\examples\\hello.p"cargo run -p jc-cli --offline -- progress-plan --action check --exe $ProgressExe --helper $Helper --source $Source --output-dir $Job --cpstream $CpStream --cpinternal $CpInternalWrite-Host "Request prepared in $Job"Write-Host "Run the printed Progress command only in an authorized development environment."